const pending = [...queue.pending];
const rerun = [...queue.rerun];
let running = queue.running;
for (const id of ids) {
  if (id === running) {
    if (!rerun.includes(id)) {
      rerun.push(id);
    }
  } else if (!pending.includes(id)) {
    pending.push(id);
  }
}
return { pending, running, rerun };
